// Keys decide identity. Index keys attach state to positions, not items.
import { useState } from 'react';

type Todo = { id: string; text: string };

function TodoRow({ todo }: { todo: Todo }) {
  const [draft, setDraft] = useState(todo.text); // local state lives with this fiber
  return <input value={draft} onChange={(e) => setDraft(e.target.value)} />;
}

export function TodoList({ todos }: { todos: Todo[] }) {
  return (
    <ul>
      {/* BAD: insert at the top and every draft shifts down one row */}
      {todos.map((t, i) => (
        <li key={i}>
          <TodoRow todo={t} />
        </li>
      ))}
      {/* GOOD: stable identity from the data */}
      {todos.map((t) => (
        <li key={t.id}>
          <TodoRow todo={t} />
        </li>
      ))}
    </ul>
  );
}

// Resetting state on purpose: a new key means a new component instance.
export function EditUser({ user }: { user: { id: string; name: string } }) {
  return <ProfileForm key={user.id} initialName={user.name} />;
}

function ProfileForm({ initialName }: { initialName: string }) {
  const [name, setName] = useState(initialName); // re-initialised when key changes
  return <input value={name} onChange={(e) => setName(e.target.value)} />;
}

// Batching: one render for all three updates (React 18+, any context).
export function useSaveButton() {
  const [count, setCount] = useState(0);
  const [saving, setSaving] = useState(false);
  async function onSave() {
    setSaving(true);
    await fetch('/api/save', { method: 'POST' });
    setCount((c) => c + 1); // updater: correct even if called several times
    setSaving(false); // batched with the line above into a single render
  }
  return { count, saving, onSave };
}

