// Context splitting plus a selector store: consumers re-render only for the slice they read.
import { createContext, useContext, useMemo, useState, useSyncExternalStore, type ReactNode } from 'react';

// 1. Split by update frequency: theme rarely changes, cart changes often.
const ThemeContext = createContext<'light' | 'dark'>('light');

export function Providers({ children }: { children: ReactNode }) {
  const [theme] = useState<'light' | 'dark'>('light');
  return <ThemeContext.Provider value={theme}>{children}</ThemeContext.Provider>;
}

export const useTheme = () => useContext(ThemeContext);

// 2. A tiny external store with selectors for the hot state.
type Cart = { items: { sku: string; qty: number }[]; coupon: string | null };
type Listener = () => void;

function createStore<T>(initial: T) {
  let state = initial;
  const listeners = new Set<Listener>();
  return {
    get: () => state,
    set(next: (prev: T) => T) {
      state = next(state);
      listeners.forEach((l) => l());
    },
    subscribe(l: Listener) {
      listeners.add(l);
      return () => listeners.delete(l);
    },
  };
}

export const cartStore = createStore<Cart>({ items: [], coupon: null });

export function useCart<S>(selector: (c: Cart) => S): S {
  // Re-renders only when the selected value changes (Object.is).
  return useSyncExternalStore(cartStore.subscribe, () => selector(cartStore.get()));
}

export function CartBadge() {
  const count = useCart((c) => c.items.reduce((n, i) => n + i.qty, 0)); // number: stable compare
  return <span aria-label={`${count} items in cart`}>{count}</span>;
}

export function CouponLabel() {
  const coupon = useCart((c) => c.coupon); // unaffected by item changes
  const label = useMemo(() => (coupon ? `Coupon ${coupon}` : 'No coupon'), [coupon]);
  return <p>{label}</p>;
}
// Note: selectors must return stable values; returning a new array each call would loop.

// app/products/[id]/page.tsx (Server Component by default)
import 'server-only'; // build fails if this module is ever imported into client code
import { Suspense } from 'react';
import { db } from '@/lib/db';
import { renderMarkdown } from '@/lib/markdown'; // heavy library, stays on the server
import { AddToCart } from './add-to-cart';
import { Tabs } from './tabs';
import { ReviewList } from './review-list';

type ProductDTO = { id: string; name: string; price: number; sku: string };

async function getProduct(id: string): Promise<ProductDTO | null> {
  const row = await db.product.findUnique({ where: { id } });
  // Map to a plain DTO: never pass ORM instances or internal fields to the client.
  return row ? { id: row.id, name: row.name, price: row.priceCents / 100, sku: row.sku } : null;
}

export default async function ProductPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const product = await getProduct(id);
  if (!product) return <p>Not found</p>;

  const reviewsPromise = db.review.findMany({ where: { productId: id }, take: 20 }); // not awaited
  const { descriptionMd } = await db.productContent.findUniqueOrThrow({ where: { productId: id } });
  const description = await renderMarkdown(descriptionMd); // returns React elements, not HTML strings

  return (
    <main>
      <h1>{product.name}</h1>
      {/* Client leaf: only this ships JS. Props are serialisable primitives. */}
      <AddToCart sku={product.sku} price={product.price} />
      {/* Donut: the client Tabs wrapper receives server-rendered children. */}
      <Tabs labels={['Description', 'Reviews']}>
        <article>{description}</article>
        <Suspense fallback={<p>Loading reviews...</p>}>
          {/* A promise crosses the boundary; the client unwraps it with use(). */}
          <ReviewList reviews={reviewsPromise} />
        </Suspense>
      </Tabs>
    </main>
  );
}

