// app/cart/actions.ts — a Server Action treated as the public endpoint it is.
'use server';
import { z } from 'zod';
import { updateTag } from 'next/cache';
import { requireSession } from '@/lib/auth';
import { db } from '@/lib/db';

const AddInput = z.object({ sku: z.string().regex(/^[A-Z0-9-]{3,32}$/), qty: z.number().int().min(1).max(10) });

export type AddResult = { ok: true; count: number } | { ok: false; error: string };

export async function addToCart(_prev: AddResult | null, form: FormData): Promise<AddResult> {
  const session = await requireSession(); // 1. authenticate: never trust that the UI hid the button
  const parsed = AddInput.safeParse({ sku: form.get('sku'), qty: Number(form.get('qty')) }); // 2. validate
  if (!parsed.success) return { ok: false, error: 'Invalid input' };

  const product = await db.product.findUnique({ where: { sku: parsed.data.sku } });
  if (!product?.active) return { ok: false, error: 'Unavailable' }; // 3. authorise against real data

  await db.cartLine.upsert({
    where: { userId_sku: { userId: session.userId, sku: parsed.data.sku } },
    create: { userId: session.userId, sku: parsed.data.sku, qty: parsed.data.qty },
    update: { qty: { increment: parsed.data.qty } },
  });
  updateTag(`cart-${session.userId}`); // read-your-writes: the response carries fresh server UI
  const count = await db.cartLine.count({ where: { userId: session.userId } });
  return { ok: true, count }; // 4. return only what the client needs
}

