// Suspense with lazy code, a cached promise, an error boundary, and a key to reset on new input.
'use client';
import { Component, Suspense, lazy, use, type ReactNode } from 'react';

const Chart = lazy(() => import('./chart')); // code-split; suspends until the chunk loads

// A tiny promise cache: use() needs the SAME promise across renders.
const cache = new Map<string, Promise<Result[]>>();
type Result = { id: string; title: string };

function search(q: string): Promise<Result[]> {
  let p = cache.get(q);
  if (!p) {
    p = fetch(`/api/search?q=${encodeURIComponent(q)}`).then((r) => {
      if (!r.ok) throw new Error(`Search failed: ${r.status}`);
      return r.json() as Promise<Result[]>;
    });
    cache.set(q, p);
  }
  return p;
}

function Results({ q }: { q: string }) {
  const results = use(search(q)); // suspends until resolved; throws to the error boundary on reject
  return (
    <ul>
      {results.map((r) => (
        <li key={r.id}>{r.title}</li>
      ))}
    </ul>
  );
}

class ErrorBoundary extends Component<{ fallback: ReactNode; children: ReactNode }, { failed: boolean }> {
  state = { failed: false };
  static getDerivedStateFromError() {
    return { failed: true };
  }
  render() {
    return this.state.failed ? this.props.fallback : this.props.children;
  }
}

export function SearchPage({ q }: { q: string }) {
  return (
    <>
      <ErrorBoundary key={`err-${q}`} fallback={<p role="alert">Search failed. Try again.</p>}>
        {/* key resets the boundary so a new query shows the skeleton, not stale results */}
        <Suspense key={q} fallback={<p aria-busy="true">Searching...</p>}>
          <Results q={q} />
        </Suspense>
      </ErrorBoundary>
      <Suspense fallback={<div style={{ height: 240 }} />}>
        <Chart />
      </Suspense>
    </>
  );
}

// Tabs that switch in a transition (no fallback flash) and a deferred, memoised heavy list.
'use client';
import { memo, Suspense, useDeferredValue, useState, useTransition } from 'react';

type Tab = 'about' | 'posts' | 'contact';

export function ProfileTabs({ panels }: { panels: Record<Tab, React.ReactNode> }) {
  const [tab, setTab] = useState<Tab>('about');
  const [isPending, startTransition] = useTransition();

  return (
    <div>
      <div role="tablist">
        {(Object.keys(panels) as Tab[]).map((t) => (
          <button
            key={t}
            role="tab"
            aria-selected={tab === t}
            onClick={() => startTransition(() => setTab(t))} // old panel stays visible while the new one loads
          >
            {t}
          </button>
        ))}
      </div>
      <div role="tabpanel" style={{ opacity: isPending ? 0.6 : 1 }}>
        <Suspense fallback={<p>Loading...</p>}>{panels[tab]}</Suspense>
      </div>
    </div>
  );
}

const SlowList = memo(function SlowList({ query, items }: { query: string; items: string[] }) {
  const q = query.toLowerCase();
  const visible = items.filter((i) => i.toLowerCase().includes(q)); // expensive for large lists
  return (
    <ul>
      {visible.slice(0, 200).map((i) => (
        <li key={i}>{i}</li>
      ))}
    </ul>
  );
});

export function FilterBox({ items }: { items: string[] }) {
  const [query, setQuery] = useState('');
  const deferred = useDeferredValue(query); // urgent render keeps the old value, so SlowList bails out
  return (
    <>
      <input value={query} onChange={(e) => setQuery(e.target.value)} aria-label="Filter" />
      <div style={{ opacity: query !== deferred ? 0.5 : 1 }}>
        <SlowList query={deferred} items={items} />
      </div>
    </>
  );
}

// React 19 async transition: isPending covers the whole async function.
export function useSaveDraft(save: (text: string) => Promise<void>) {
  const [isPending, startTransition] = useTransition();
  const [savedAt, setSavedAt] = useState<number | null>(null);
  function onSave(text: string) {
    startTransition(async () => {
      await save(text);
      startTransition(() => setSavedAt(Date.now())); // updates after await need their own wrapper
    });
  }
  return { isPending, savedAt, onSave };
}
